java('evaluation','DemoScenario',r'''import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
public final class DemoScenario {
 private DemoScenario(){}
 public static void run(Path data,int count)throws Exception{AuthorizationFilter auth=new AuthorizationFilter();List<AuthorizationFilter.Access> access=new ArrayList<>();for(int i=0;i<3;i++)access.add(auth.update("demo"+i,"tenant"+i,Set.of("public"),true));long bytes;try(SearchEngine engine=new SearchEngine(data,auth)){var generated=WorkloadGenerator.generate(engine.contentStore(),count,7007);bytes=generated.bytes();for(int i=0;i<3;i++)engine.ingest(access.get(i),"seed-"+count,generated.manifests().get(i),GenerationBuilder.Fault.none(),()->false);var request=new SearchEngine.Request("resolveGeneration0",10,null,Map.of());var result=engine.search("demo0",request);if(result.results().isEmpty()||!result.results().getFirst().path().equals("src/Component0.java"))throw new AssertionError("identifier retrieval");var prose=engine.search("demo0",new SearchEngine.Request("atomic publication",10,null,Map.of()));if(prose.totalHits()<count/3)throw new AssertionError("prose retrieval");var denied=new SnapshotManifest("tenant0","denied","v1",false,List.of(new SnapshotManifest.Entry("Private.java",engine.contentStore().put("inaccessibleSecret".getBytes(StandardCharsets.UTF_8)),"java","source",List.of("inaccessibleSecret"),"", "")),Set.of());var admin=auth.update("admin","tenant0",Set.of("public","denied"),true);engine.ingest(admin,"denied",denied,GenerationBuilder.Fault.none(),()->false);if(engine.search("demo0",new SearchEngine.Request("inaccessibleSecret",10,null,Map.of())).totalHits()!=0||!engine.suggest("demo0","inaccessible").isEmpty())throw new AssertionError("authorization leak");SnapshotManifest initial=generated.manifests().getFirst();String old=engine.generations("tenant0").currentId();var replacement=new SnapshotManifest("tenant0","public","v2",true,initial.entries().subList(1,initial.entries().size()),Set.of(initial.entries().getFirst().path()));try(ExecutorService searches=Executors.newSingleThreadExecutor()){Future<?> concurrent=searches.submit(()->{try{for(int n=0;n<100;n++){var response=engine.search("demo0",new SearchEngine.Request("atomic",10,null,Map.of()));long before=initial.entries().size(),after=before-1;if(response.totalHits()!=before&&response.totalHits()!=after)throw new AssertionError("mixed-generation count");}}catch(IOException e){throw new UncheckedIOException(e);}});engine.ingest(access.getFirst(),"replacement-"+count,replacement,GenerationBuilder.Fault.none(),()->false);concurrent.get(60,TimeUnit.SECONDS);}if(old.equals(engine.generations("tenant0").currentId()))throw new AssertionError("replacement not published");var interrupted=new SnapshotManifest("tenant0","public","interrupted",false,initial.entries(),Set.of());try{engine.ingest(access.getFirst(),"interrupted-"+count,interrupted,boundary->{if(boundary==GenerationBuilder.Boundary.BEFORE_COMMIT)throw new IOException("demonstration interrupted build");},()->false);throw new AssertionError("failure not injected");}catch(IOException expected){if(!expected.getMessage().contains("demonstration"))throw expected;}}try(SearchEngine recovered=new SearchEngine(data,auth)){var response=recovered.search("demo0",new SearchEngine.Request("atomic",10,null,Map.of()));if(response.totalHits()!=(count+2)/3-1)throw new AssertionError("restart atomicity");if(recovered.search("demo0",new SearchEngine.Request("inaccessibleSecret",10,null,Map.of())).totalHits()!=0)throw new AssertionError("restart isolation");}System.out.println("{\"scenario\":\"indexforge-transactional-demo-v1\",\"seed\":7007,\"documents\":"+count+",\"sourceBytes\":"+bytes+",\"tenants\":3,\"assertions\":\"passed\"}");}
}
''')
java('evaluation','PerformanceHarness',r'''import java.io.*;
import java.lang.management.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import com.sun.management.OperatingSystemMXBean;
public final class PerformanceHarness {
 private PerformanceHarness(){}
 public static void run(Path data,Path output,int documents,int seconds)throws Exception{if(Runtime.getRuntime().maxMemory()>2147483648L)throw new IllegalArgumentException("declare heap at most2GiB");AuthorizationFilter auth=new AuthorizationFilter();List<AuthorizationFilter.Access> access=new ArrayList<>();for(int t=0;t<3;t++)access.add(auth.update("load"+t,"tenant"+t,Set.of("public"),true));Files.createDirectories(output);try(SearchEngine engine=new SearchEngine(data,auth)){var generated=WorkloadGenerator.generate(engine.contentStore(),documents,7007);for(int t=0;t<3;t++)engine.ingest(access.get(t),"benchmark-"+documents,generated.manifests().get(t),GenerationBuilder.Fault.none(),()->false);for(int i=0;i<150;i++)engine.search("load"+(i%3),request(i,documents));OperatingSystemMXBean os=(OperatingSystemMXBean)ManagementFactory.getOperatingSystemMXBean();List<String> runs=new ArrayList<>();for(int run=0;run<3;run++){long gcBefore=gcTime(),cpuBefore=os.getProcessCpuTime(),start=System.nanoTime();int requests=seconds*30;long[] latency=new long[requests];AtomicInteger errors=new AtomicInteger(),queued=new AtomicInteger(),peak=new AtomicInteger();try(ExecutorService clients=Executors.newFixedThreadPool(8)){List<Future<?>> tasks=new ArrayList<>();for(int i=0;i<requests;i++){long scheduled=start+(long)i*1_000_000_000L/30;long delay=scheduled-System.nanoTime();if(delay>0)java.util.concurrent.locks.LockSupport.parkNanos(delay);final int index=i;int q=queued.incrementAndGet();peak.accumulateAndGet(q,Math::max);tasks.add(clients.submit(()->{try{engine.search("load"+(index%3),request(index+runOffset(index),documents));}catch(Exception e){errors.incrementAndGet();}finally{latency[index]=System.nanoTime()-scheduled;queued.decrementAndGet();}}));}for(Future<?> task:tasks)task.get(60,TimeUnit.SECONDS);}long duration=System.nanoTime()-start;long cpu=os.getProcessCpuTime()-cpuBefore;Arrays.sort(latency);StringBuilder raw=new StringBuilder("latencyNanos\n");for(long l:latency)raw.append(l).append('\n');Files.writeString(output.resolve("run-"+run+"-latencies.csv"),raw);String json="{\"run\":"+run+",\"requests\":"+requests+",\"offeredRps\":30,\"completedRps\":"+(requests*1e9/duration)+",\"errors\":"+errors+",\"p50Ms\":"+percentile(latency,.5)+",\"p95Ms\":"+percentile(latency,.95)+",\"p99Ms\":"+percentile(latency,.99)+",\"gcMillis\":"+(gcTime()-gcBefore)+",\"processCpuNanos\":"+cpu+",\"queuePeak\":"+peak+",\"durationNanos\":"+duration+"}";runs.add(json);System.out.println(json);}String metadata="{\"schemaVersion\":1,\"boundary\":\"shared application search including leases ACL facets explanations and warm bounded response cache; excludes HTTP\",\"seed\":7007,\"documents\":"+documents+",\"sourceBytes\":"+generated.bytes()+",\"heapMaxBytes\":"+Runtime.getRuntime().maxMemory()+",\"warmupRequests\":150,\"runs\":["+String.join(",",runs)+"]}";Files.writeString(output.resolve("summary.json"),metadata);}}
 private static int runOffset(int i){return i*17;}
 private static SearchEngine.Request request(int i,int documents){return new SearchEngine.Request(i%4==0?"atomic publication":i%4==1?"source repository":i%4==2?"resolveGeneration"+((i*3)%documents):"reader lease",10,null,Map.of());}
 private static long gcTime(){return ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionTime).filter(n->n>=0).sum();}
 private static double percentile(long[] sorted,double p){return sorted[(int)Math.ceil(sorted.length*p)-1]/1e6;}
}
''')
java('cli','IndexForgeCli',r'''import java.nio.file.*;
import java.util.*;
public final class IndexForgeCli {
 private IndexForgeCli(){}
 public static void main(String[] args)throws Exception{if(args.length<2)throw new IllegalArgumentException("command data [arguments]; see contracts/cli.md");String command=args[0];Path data=Path.of(args[1]);if(command.equals("up")){Files.createDirectories(data.resolve("sources"));System.out.println("Prepared local IndexForge data "+data.toAbsolutePath());return;}if(command.equals("demo")){DemoScenario.run(data,args.length>2?Integer.parseInt(args[2]):20000);return;}if(command.equals("evaluate")){RelevanceEvaluator.run(data,Path.of(args[2]),Path.of(args[3]),args.length>4?args[4]:"development");return;}if(command.equals("benchmark")){PerformanceHarness.run(data,Path.of(args[2]),args.length>3?Integer.parseInt(args[3]):100000,args.length>4?Integer.parseInt(args[4]):30);return;}if(args.length<4)throw new IllegalArgumentException("tenant and repository required");String tenant=args[2],repository=args[3];AuthorizationFilter auth=new AuthorizationFilter();var access=auth.update("local-cli",tenant,Set.of(repository),true);try(SearchEngine engine=new SearchEngine(data,auth)){switch(command){case "ingest"->{if(args.length<9)throw new IllegalArgumentException("ingest data tenant repo sourceRoot relativePath revision key [deletedPath...]");var reader=new SafeSourceReader(Path.of(args[4]),SafeSourceReader.Limits.defaults(),engine.contentStore());Set<String> deleted=args.length>8?new TreeSet<>(Arrays.asList(args).subList(8,args.length)):Set.of();var manifest=reader.directory(tenant,repository,args[6],Path.of(args[5]),false,deleted,()->false);var job=engine.ingest(access,args[7],manifest,GenerationBuilder.Fault.none(),()->false);System.out.println("job="+job.id()+" manifest="+job.manifestHash());}case "search"->{if(args.length<5)throw new IllegalArgumentException("search text required");var response=engine.search(access.principal(),new SearchEngine.Request(args[4],20,null,Map.of()));System.out.println("generation="+response.generationId()+" total="+response.totalHits()+" relation="+response.relation());for(var hit:response.results())System.out.println(hit.score()+"\t"+hit.path()+"\t"+hit.snippet().replace('\n',' '));}case "reindex"->{engine.reindex(access);System.out.println("Reindex committed generation="+engine.generations(tenant).currentId());}case "verify-generation"->{try(var lease=engine.generations(tenant).acquire()){System.out.println("verified generation="+lease.id()+" documents="+lease.reader().numDocs());}}default->throw new IllegalArgumentException("unsupported command "+command);}}}
}
''')
